class AsyncFundingRateResource(AsyncResource):
    """`/v1/funding/rate` and its sub-routes."""

    history: AsyncFundingRateHistoryResource

    def __init__(self, client: Any) -> None:
        super().__init__(client)
        self.history = AsyncFundingRateHistoryResource(client)

    _route = RouteSpec(path='/v1/funding/rate', method='GET', shape='object', model=m.FundingRate, paginated=False, path_params=(), max_limit=None, range_mode=False)

    async def __call__(
        self,
        symbol: str,
        *,
        live: bool | None = None,
        fields: Fields | None = None,
        request_options: RequestOptions | None = None,
    ) -> Response[m.FundingRate | None]:
        """GET /v1/funding/rate — Latest settled funding rate

        The last fully settled 8-hour funding window, normalised to 8 h and weighted by the
        open interest of each venue at that time. `?live=1` for the window in progress.
        `time` is the START of the period; the period is `[time, period_end)` and
        `settled_at` says when its last settlement was paid — compare it with the `time` of
        `/v1/funding/next` (the next settlement), not with this `time`. `rate_pct` is in
        percent per 8 h.

        Args:
            symbol: Trading pair, e.g. `BTCUSDT`. Required. The 22 served pairs: `GET
                /v1/symbols`. Case-insensitive (`btcusdt` works; the envelope gives the
                canonical `BTCUSDT`). An unknown pair returns 422 `invalid_symbol` with the
                accepted list.
            live: `1` or `true` to return the CURRENT, still-open period computed on the fly
                (`is_closed: false`). Default: the last closed period only.
            fields: Only return these fields of each row (a list or a comma-separated
                string; dotted paths reach nested keys). Rows are then partial and not
                validated.
            request_options: Per-request `timeout`, `max_retries` or extra `headers`.
        """
        return await self._call(self._route, {'symbol': symbol, 'live': live, 'fields': fields}, request_options)


